                     )
                 }
                 return SubmitAdmissionResult.Blocked(e.message ?: "persist_failed")
             }
 
             // Post-persist & Pre-enqueue barrier check:
             checkSessionBarrier(session)
 
             try {
                 enqueueWorkSync(report, replace = false)
