      */
     suspend fun getOrFetchBitmap(
         context: Context,
         url: String,
         purpose: String = "preview",
         report: TesterReport? = null,
         descriptor: ScreenshotDescriptor? = null,
     ): Bitmap? {
         if (url.isBlank()) return null

