+                        return@launch
+                    }
+                    _uiState.update {
+                        it.copy(
+                            isLoading = false,
+                            isBackgroundSyncing = false,
+                            isAuthenticated = true,
+                            profile = profile,
+                            error = localizer.get(R.string.profile_account_locked)
+                        )
+                    }
+                    return@launch
+                }
+                val logs = dashboard?.creditLogs ?: campaignRepository.getMyCreditLogs(forceRefresh = forceRefresh)
+                val slots = campaignRepository.getMySlotsInfo(forceRefresh = forceRefresh)
+
+                if (seq != refreshSequence.get() || initialGen != SessionCacheManager.currentGeneration() || initialUid != authRepository.currentUserId()) {
+                    return@launch
+                }
+
+                _uiState.update {
+                    it.copy(
+                        isLoading = false,
+                        isBackgroundSyncing = false,
+                        isAuthenticated = true,
+                        profile = profile,
+                        email = authRepository.currentUserEmail(),
+                        creditLogs = logs,
+                        slots = slots,
+                        error = null,
+                    )
+                }
+            } catch (e: Exception) {
+                if (e is CancellationException) throw e
+                if (seq != refreshSequence.get() || initialGen != SessionCacheManager.currentGeneration() || initialUid != authRepository.currentUserId()) {
+                    return@launch
+                }
+                _uiState.update {
+                    it.copy(
+                        isLoading = false,
+                        isBackgroundSyncing = false,
+                        error = if (_uiState.value.profile == null) friendlyError(e, localizer) else null
+                    )
+                }
+            }
+        }
+    }
+
+    private val isSlotActionInProgress = java.util.concurrent.atomic.AtomicBoolean(false)
+    private var lastSlotIntentKey: String? = null
+    private var lastSlotRequestId: String? = null
+
+    fun unlockOrRenewSlot(
+        slotNumber: Int,
+        expectedCost: Int? = null,
+        expectedRevision: String? = null,
+    ) {
+        if (!isSlotActionInProgress.compareAndSet(false, true)) return
+        val currentSlot = _uiState.value.slots.find { it.slotNumber == slotNumber }
+        val cost = expectedCost ?: currentSlot?.cost ?: SlotInfo.costForSlot(slotNumber)
+        val revision = expectedRevision ?: currentSlot?.policyRevision
+
+        if (revision == null) {
+            isSlotActionInProgress.set(false)
+            _uiState.update {
+                it.copy(error = localizer.get(R.string.admin_policy_quote_unavailable))
+            }
+            return
+        }
+
+        val credits = _uiState.value.profile?.credits ?: 0
+        if (credits < cost) {
+            isSlotActionInProgress.set(false)
+            _uiState.update {
+                it.copy(error = localizer.get(R.string.profile_slot_cost_format, cost, slotNumber, credits))
+            }
+            return
+        }
+
+        val uid = authRepository.currentUserId() ?: run {
+            isSlotActionInProgress.set(false)
+            return
+        }
+        val gen = SessionCacheManager.currentGeneration()
+
+        val pending = FinancialIntentStore.peekSlotIntent(localizer.context, uid, slotNumber)
+        val intentToUse = if (pending != null && pending.expectedCost == cost && pending.expectedRevision == revision) {
+            pending
+        } else {
+            val newIntent = PendingSlotIntent(
+                userId = uid,
+                slotNumber = slotNumber,
+                expectedCost = cost,
+                expectedRevision = revision,
+                renewalDays = currentSlot?.renewalDays ?: 30,
+                clientRequestId = java.util.UUID.randomUUID().toString(),
+            )
+            FinancialIntentStore.saveSlotIntent(localizer.context, newIntent)
+            newIntent
+        }
+
+        viewModelScope.launch {
+            _uiState.update { it.copy(isUnlockingSlot = true, error = null) }
+            try {
+                val result = campaignRepository.unlockOrRenewSlotV2(
+                    slotNumber = intentToUse.slotNumber,
+                    clientRequestId = intentToUse.clientRequestId,
+                    expectedCost = intentToUse.expectedCost,
+                    expectedRevision = intentToUse.expectedRevision,
+                )
+                if (authRepository.currentUserId() != uid || SessionCacheManager.currentGeneration() != gen) return@launch
+
+                FinancialIntentStore.clearSlotIntent(localizer.context, uid, slotNumber)
+
+                _uiState.update { state ->
+                    val updatedProfile = state.profile?.copy(credits = result.balance)
+                    state.copy(
+                        profile = updatedProfile,
+                        unlockSuccessMsg = localizer.get(R.string.profile_slot_success_format, slotNumber),
+                    )
+                }
+                refresh()
+            } catch (e: Exception) {
+                if (e is CancellationException) throw e
+                if (authRepository.currentUserId() != uid || SessionCacheManager.currentGeneration() != gen) return@launch
+
+                val isConflict = e.message?.contains("BUSINESS_POLICY_CONFLICT", ignoreCase = true) == true ||
+                        e.message?.contains("BUSINESS_POLICY_PRICE_MISMATCH", ignoreCase = true) == true
+
+                if (isConflict) {
+                    FinancialIntentStore.clearSlotIntent(localizer.context, uid, slotNumber)
+                    refresh()
+                    _uiState.update {
+                        it.copy(error = friendlyBusinessPolicyError(e, localizer))
+                    }
+                } else {
+                    val msg = when {
+                        e.message?.contains("INSUFFICIENT_CREDITS") == true -> localizer.get(R.string.profile_insufficient_credits)
+                        e.message?.contains("PREVIOUS_SLOT_NOT_ACTIVE") == true -> localizer.get(R.string.profile_prev_slot_required_format, slotNumber - 1)
+                        else -> friendlyBusinessPolicyError(e, localizer)
+                    }
+                    _uiState.update { it.copy(error = msg) }
+                }
+            } finally {
+                if (authRepository.currentUserId() == uid && SessionCacheManager.currentGeneration() == gen) {
+                    isSlotActionInProgress.set(false)
+                    _uiState.update { it.copy(isUnlockingSlot = false) }
+                }
+            }
+        }
+    }
+
+    fun clearUnlockSuccess() {
+        _uiState.update { it.copy(unlockSuccessMsg = null) }
+    }
+
+    fun signIn(context: Context) {
+        if (_uiState.value.isActionLoading) return
+        viewModelScope.launch {
+            _uiState.update { it.copy(isActionLoading = true, error = null) }
+            when (val outcome = requestGoogleSignIn(context, BuildConfig.GOOGLE_WEB_CLIENT_ID)) {
+                is GoogleSignInOutcome.Cancelled -> {
+                    _uiState.update { it.copy(isActionLoading = false) }
+                }
+                is GoogleSignInOutcome.Error -> {
+                    _uiState.update { it.copy(isActionLoading = false, error = outcome.message) }
+                }
+                is GoogleSignInOutcome.Success -> {
+                    try {
+                        authRepository.signInWithGoogle(
+                            idToken = outcome.result.idToken,
+                            displayName = outcome.result.displayName,
+                            avatarUrl = outcome.result.avatarUrl,
+                        )
+                        _uiState.update { it.copy(isActionLoading = false) }
+                        refresh()
+                    } catch (e: Exception) {
+                        _uiState.update {
+                            it.copy(
+                                isActionLoading = false,
+                                error = localizer.get(R.string.auth_sign_in_failed_format, friendlyError(e, localizer))
+                            )
+                        }
+                    }
+                }
+            }
+        }
+    }
+
+    fun setReminderEnabled(enabled: Boolean) {
+        viewModelScope.launch {
+            app.settingsRepository.setReminderEnabled(enabled)
+            if (enabled) app.scheduleDailyReminder() else app.cancelDailyReminder()
+        }
+    }
+
+    fun setAppLanguage(languageCode: String) {
+        viewModelScope.launch {
+            app.settingsRepository.setAppLanguage(languageCode)
+        }
+    }
+
+    fun setAppTheme(theme: String) {
+        viewModelScope.launch {
+            app.settingsRepository.setAppTheme(theme)
+        }
+    }
+
+    fun changePassword(newPass: String, confirmPass: String, onSuccess: () -> Unit) {
+        if (newPass.length < 6) {
+            _uiState.update { it.copy(error = localizer.get(R.string.auth_password_min_length)) }
+            return
+        }
+        if (newPass != confirmPass) {
+            _uiState.update { it.copy(error = localizer.get(R.string.auth_password_mismatch)) }
+            return
+        }
+
+        viewModelScope.launch {
+            _uiState.update { it.copy(isChangingPassword = true, error = null) }
+            try {
+                authRepository.changePassword(newPass)
+                _uiState.update {
+                    it.copy(
+                        isChangingPassword = false,
+                        changePasswordSuccessMsg = localizer.get(R.string.profile_password_changed)
+                    )
+                }
+                onSuccess()
+            } catch (e: Exception) {
+                _uiState.update {
+                    it.copy(
+                        isChangingPassword = false,
+                        error = localizer.get(R.string.profile_password_change_failed_format, friendlyError(e, localizer))
+                    )
+                }
+            }
+        }
+    }
+
+    fun clearChangePasswordSuccess() {
+        _uiState.update { it.copy(changePasswordSuccessMsg = null) }
+    }
+
+    /**
+     * Gửi phản hồi liên hệ/báo lỗi cho Admin. Tự đính kèm phiên bản app và
+     * thông tin thiết bị để Admin dễ tái hiện lỗi.
+     */
+    fun submitContactReport(category: String, message: String, onSuccess: () -> Unit) {
+        val trimmed = message.trim()
+        if (trimmed.isEmpty()) {
+            _uiState.update { it.copy(error = localizer.get(R.string.contact_message_required)) }
+            return
+        }
+        if (_uiState.value.isSendingReport) return
+
+        viewModelScope.launch {
+            _uiState.update { it.copy(isSendingReport = true, error = null) }
+            try {
+                campaignRepository.submitContactReport(
+                    category = category,
+                    message = trimmed,
+                    appVersion = "${BuildConfig.VERSION_NAME} (${BuildConfig.VERSION_CODE})",
+                    platform = "Android ${android.os.Build.VERSION.RELEASE}",
+                    deviceModel = "${android.os.Build.MANUFACTURER} ${android.os.Build.MODEL}".trim(),
+                )
+                _uiState.update {
+                    it.copy(
+                        isSendingReport = false,
+                        reportSuccessMsg = localizer.get(R.string.contact_send_success),
+                    )
+                }
+                onSuccess()
+            } catch (e: Exception) {
+                _uiState.update {
+                    it.copy(
+                        isSendingReport = false,
+                        error = localizer.get(R.string.contact_send_failed_format, friendlyError(e, localizer)),
+                    )
+                }
+            }
+        }
+    }
+
+    fun clearReportSuccess() {
+        _uiState.update { it.copy(reportSuccessMsg = null) }
+    }
+
+    fun signOut() {
+        viewModelScope.launch {
+            // Clears remote session (best effort), RAM caches and the disk snapshot.
+            app.performSignOut()
+            _uiState.update {
+                it.copy(
+                    signedOut = true,
+                    isAuthenticated = false,
+                    profile = null,
+                    email = null,
+                )
+            }
+        }
+    }
+}

