+  let content = fs.readFileSync(filePath, 'utf8');
+  const eol = content.includes('\r\n') ? '\r\n' : '\n';
+  const normalizedTarget = targetText.replace(/\r\n|\n/g, eol);
+  const normalizedReplacement = replacementText.replace(/\r\n|\n/g, eol);
