    if (state.testStartedAtMs == null) {
        _uiState.update { it.copy(errorMessage = appContext.getString(R.string.mission_report_test_needed_hint)) }
        return
    }
    val elapsed = SystemClock.elapsedRealtime() - state.testStartedAtMs
    if (elapsed < 10_000L) {
        val remainingSec = ((10_000L - elapsed + 999) / 1000).toInt()
        _uiState.update { it.copy(errorMessage = appContext.getString(R.string.mission_report_test_remaining_hint, remainingSec)) }
        return
    }

    // If report was rejected, must require a new primary photo
    if (state.todayReport?.isRejected == true) {
        val hasNewPhoto = state.preparedScreenshots.isNotEmpty()
        val primarySame = state.preparedScreenshots.firstOrNull()?.imageHash == state.todayReport.imageHash
        if (!hasNewPhoto || primarySame) {
            _uiState.update { it.copy(errorMessage = appContext.getString(R.string.campaign_resubmit_new_photo_required)) }
            return
        }
    } else if (state.preparedScreenshots.isEmpty() && state.todayReport?.screenshotUrl == null) {
        _uiState.update { it.copy(errorMessage = appContext.getString(R.string.mission_report_photo_required)) }
        return
    }
}

