    val currentRequests = list(context).count { it.completedResult == null }
    if (currentRequests + newRequestsCount > MAX_FILES) return false
    val metadataBudget = 8_192L * newRequestsCount
    if (currentBytes + estimatedBytes + metadataBudget > MAX_TOTAL_BYTES) return false
    return true
}

