    val draft = loadDraft(context, userId, campaignId, missionId, reportDate) ?: return false
    if (draft.comment == expectedComment && draft.rating == expectedRating && draft.preparedImages.map { it.uploadId } == expectedImageIds) {
        clearDraft(context, userId, campaignId, missionId, reportDate)
        return true
    }
    return false
}

