fun retry(campaignId: String? = null, missionId: String? = null) {
    val targetState = if (missionId != null && campaignId != null) {
        currentStateForMission(campaignId, missionId)
    } else if (campaignId != null) {
        currentStateForCampaign(campaignId)
    } else {
        _state.value
